window.PTAB_FIND = (nid, isle) => { const M = D.isle || {}; if (isle && M[isle.replace(/_club$/, "") + "|" + nid]) return M[isle.replace(/_club$/, "") + "|" + nid]; const k = Object.keys(M).find(x => x.endsWith("|" + nid)); return k ? M[k] : null; };
